package platform.contentapi.execution;

import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import platform.contentapi.management.*;
import tools.jackson.databind.JsonNode;
import static platform.contentapi.execution.PreflightFailure.Code.*;
import static platform.contentapi.execution.PreflightFailure.need;

/** Internal D5a successful path only. No production dispatch, activation or Content recovery. */
final class RssContentExecution {
    enum Boundary { INTENT, BEFORE_AUTHORIZATION, AUTHORIZED, CHILD_STARTED, HEARTBEAT, AFTER_CHILD, VERIFIED, BEFORE_CHECKPOINT, ACKNOWLEDGED }
    interface Fault {void at(String phase,Boundary boundary,WorkerRepository.Owner owner);}
    record Completed(UUID artifact,WorkerRepository.Session session,byte[] evidence){Completed{evidence=evidence.clone();}@Override public byte[] evidence(){return evidence.clone();}}
    private record Context(UUID run,UUID attempt,JsonNode frozen,JsonNode gold,JsonNode reference,RssContentRuntime runtime,String inputSha){}
    private static final class Current {WorkerRepository.Owner owner;WorkerRepository.PublicationStage stage;}
    private final JdbcTemplate jdbc;private final ManagementTransactions tx;private final WorkerRepository workers;private final Fault fault;
    RssContentExecution(JdbcTemplate j,ManagementTransactions t,WorkerRepository w){this(j,t,w,(p,b,o)->{});}
    RssContentExecution(JdbcTemplate j,ManagementTransactions t,WorkerRepository w,Fault f){jdbc=j;tx=t;workers=w;fault=f;}
    private Context context(InstallationHostGuard guard,UUID run,String runtimeId,Current current){
        JsonNode frozen;UUID attempt;if(current!=null){frozen=workers.frozenContent(guard,current.owner);attempt=current.owner.attemptId();}
        else{var rows=tx.required(()->jdbc.queryForList("SELECT captured_selection,selection_sha256,current_attempt_id FROM ddip_management.runs WHERE run_id=?",run));need(rows.size()==1,INPUT_UNAVAILABLE);var r=rows.getFirst();frozen=FrozenRunSelection.canonical((byte[])r.get("captured_selection"),(String)r.get("selection_sha256"),PreflightFiles.LARGE);attempt=(UUID)r.get("current_attempt_id");}
        need(frozen.get("pipeline").stringValue().equals("CONTENT_RSS_V1") && attempt!=null,INPUT_INVALID);var runtime=RssContentRuntime.load(jdbc,tx,guard,run,frozen,runtimeId);
        var gold=new RssGoldExecution(jdbc,tx,workers).committed(guard,run,runtime.config.get("goldRuntimeId").stringValue());if(current!=null)current.owner=workers.heartbeat(guard,current.owner);var reference=RssContentInputs.reference(frozen);
        var c=new Context(run,attempt,frozen,gold,reference,runtime,SourceJson.sha(SourceJson.canonical(RssContentInputs.dependencies(gold,reference))));check(guard,c,current);return c;
    }
    private void check(InstallationHostGuard guard,Context c,Current current){guard.checkHeld(guard.binding().installationId());c.runtime.check();tx.required(()->{RssContentInputs.check(jdbc,c.run,c.attempt,c.frozen,c.gold,c.reference);return null;});if(current!=null){if(current.stage!=null)workers.checkPublication(guard,current.stage);else workers.frozenContent(guard,current.owner);}}
    Completed execute(InstallationHostGuard guard,WorkerRepository.Owner owner,String runtimeId){
        var current=new Current();current.owner=owner;var c=context(guard,owner.runId(),runtimeId,current);UUID preparation=UUID.randomUUID();var before=new PreflightFiles(guard,c.run,c.attempt,preparation,"CHECK_INPUTS");byte[] prepare=command(c,preparation,current.owner.worker().epoch(),"PREPARE",null,null);before.write("command.json",prepare,PreflightFiles.LARGE);
        current.stage=workers.beginContent(guard,current.owner,"CHECK_INPUTS",preparation,SourceJson.sha(prepare),c.inputSha,c.inputSha,c.frozen,c.gold,c.reference);current.owner=current.stage.owner();fault.at("CHECK_INPUTS",Boundary.INTENT,current.owner);
        try{
            var prepared=child(guard,c,before,prepare,current,true).get("prepared");need(prepared!=null && SourceJson.sha(SourceJson.canonical(prepared.get("manifest"))).equals(prepared.get("fingerprint").stringValue()),RESULT_INVALID);byte[] preparationAnchor=boundAnchor(before,c,null);before.write("verified.json",preparationAnchor,65536);check(guard,c,current);RssGoldExecution.verifyStageAnchor(before);workers.checkpointContent(guard,current.stage,SourceJson.sha(preparationAnchor),c.frozen,c.gold,c.reference);current.owner=current.stage.owner();fault.at("CHECK_INPUTS",Boundary.ACKNOWLEDGED,current.owner);current.stage=null;
            String fingerprint=prepared.get("fingerprint").stringValue();UUID checkpoint=UUID.randomUUID();byte[] publish=command(c,checkpoint,current.owner.worker().epoch(),"PUBLISH",prepared,null);
            var preparationRows=tx.required(()->jdbc.queryForList("SELECT result_sha256 FROM ddip_management.stage_invocations WHERE attempt_id=? AND stage='CHECK_INPUTS' AND checkpoint_id=? AND state='VERIFIED'",c.attempt,preparation));need(preparationRows.size()==1 && SourceJson.sha(before.read("verified.json",65536)).equals(preparationRows.getFirst().get("result_sha256")),INPUT_CHANGED);
            current.stage=workers.beginContent(guard,current.owner,"PUBLISH_CONTENT",checkpoint,SourceJson.sha(publish),c.inputSha,fingerprint,c.frozen,c.gold,c.reference);current.owner=current.stage.owner();fault.at("PUBLISH_CONTENT",Boundary.INTENT,current.owner);
            var publisher=new PreflightFiles(guard,c.run,c.attempt,checkpoint,"PUBLISH_CONTENT");publisher.write("command.json",publish,PreflightFiles.LARGE);var result=child(guard,c,publisher,publish,current,true);need(Set.of("published","replayed").contains(result.get("status").stringValue()) && result.get("prepared").equals(prepared),RESULT_INVALID);
            byte[] publishedAnchor=boundAnchor(publisher,c,null);publisher.write("verified.json",publishedAnchor,65536);fault.at("PUBLISH_CONTENT",Boundary.BEFORE_CHECKPOINT,current.stage.owner());check(guard,c,current);RssGoldExecution.verifyStageAnchor(publisher);workers.checkpointContent(guard,current.stage,SourceJson.sha(publishedAnchor),c.frozen,c.gold,c.reference);current.owner=current.stage.owner();fault.at("PUBLISH_CONTENT",Boundary.ACKNOWLEDGED,current.owner);
            current.stage=null;UUID verification=UUID.randomUUID();byte[] verify=command(c,verification,current.owner.worker().epoch(),"VERIFY",prepared,null);
            current.stage=workers.beginContent(guard,current.owner,"VERIFY_RESULT",verification,SourceJson.sha(verify),c.inputSha,fingerprint,c.frozen,c.gold,c.reference);current.owner=current.stage.owner();fault.at("VERIFY_RESULT",Boundary.INTENT,current.owner);
            var verifier=new PreflightFiles(guard,c.run,c.attempt,verification,"VERIFY_RESULT");verifier.write("command.json",verify,PreflightFiles.LARGE);var verified=child(guard,c,verifier,verify,current,true);need(verified.get("status").stringValue().equals("VERIFIED") && verified.get("prepared").equals(prepared),RESULT_INVALID);fault.at("VERIFY_RESULT",Boundary.VERIFIED,current.stage.owner());
            var artifact=SourceJson.object().put("managedContentVersion",1).put("kind","CONTENT").put("productId","content-intelligence").put("contractVersion",1).put("processorRevision",1).put("nativeFingerprint",fingerprint).put("storageBindingId",c.runtime.config.get("contentBindingId").stringValue()).put("relativeAddress","v1/processor_revision=1/publication="+fingerprint);artifact.set("inputs",RssContentInputs.dependencies(c.gold,c.reference));artifact.set("verification",verified);byte[] evidence=SourceJson.canonical(artifact);verifier.write("selection.json",evidence,PreflightFiles.LARGE);byte[] anchor=boundAnchor(verifier,c,evidence);verifier.write("verified.json",anchor,65536);
            fault.at("VERIFY_RESULT",Boundary.BEFORE_CHECKPOINT,current.stage.owner());check(guard,c,current);
            var recheck=new PreflightFiles(guard,c.run,c.attempt,UUID.randomUUID(),"CHECK_INPUTS");byte[] last=command(c,verification,current.stage.owner().worker().epoch(),"RECHECK",prepared,verified);recheck.write("command.json",last,PreflightFiles.LARGE);need(child(guard,c,recheck,last,current,false).equals(verified),INPUT_CHANGED);
            for(var files:List.of(before,publisher,verifier))RssGoldExecution.verifyStageAnchor(files);need(SourceJson.sha(before.read("verified.json",65536)).equals(preparationRows.getFirst().get("result_sha256")) && Arrays.equals(anchor,boundAnchor(verifier,c,evidence)) && Arrays.equals(evidence,verifier.read("selection.json",PreflightFiles.LARGE)),INPUT_CHANGED);check(guard,c,current);
            var pubRows=tx.required(()->jdbc.queryForList("SELECT result_sha256 FROM ddip_management.stage_invocations WHERE attempt_id=? AND stage='PUBLISH_CONTENT' AND checkpoint_id=? AND state='VERIFIED'",c.attempt,checkpoint));need(pubRows.size()==1 && SourceJson.sha(publisher.read("verified.json",65536)).equals(pubRows.getFirst().get("result_sha256")),INPUT_CHANGED);
            UUID id=workers.succeedContent(guard,current.stage,SourceJson.sha(anchor),evidence,c.frozen,c.gold,c.reference);var session=current.stage.owner().worker();fault.at("VERIFY_RESULT",Boundary.ACKNOWLEDGED,current.stage.owner());return new Completed(id,new WorkerRepository.Session(session.installationId(),session.instanceId(),session.profileId(),session.profileDigest(),session.deploymentDigest(),session.hostDigest(),session.status(),session.epoch(),session.coordinatorVersion()+1,session.workerVersion()),evidence);
        }catch(PreflightFailure ex){if(current.stage!=null)workers.blockPublication(guard,current.stage,ex.code()==PROCESS_START_FAILED && ex.quiescent());throw ex;}
    }
    /** Lost final acknowledgment is resolved from committed terminal facts and independent native reads.
     * This operation never adopts an owner, registers an artifact, heartbeats or clears the slot. */
    UUID inspect(InstallationHostGuard guard,UUID run,String runtimeId){
        var c=context(guard,run,runtimeId,null);var rows=tx.required(()->jdbc.queryForList("SELECT s.checkpoint_id,s.result_sha256,a.*,r.state AS run_state,r.result_artifact_id,t.state AS attempt_state FROM ddip_management.runs r JOIN ddip_management.attempts t ON t.attempt_id=r.current_attempt_id JOIN ddip_management.stage_invocations s ON s.attempt_id=t.attempt_id JOIN ddip_management.stage_artifacts x ON x.attempt_id=s.attempt_id AND x.stage=s.stage AND x.item_ordinal=s.item_ordinal JOIN ddip_management.artifacts a ON a.artifact_id=x.artifact_id WHERE r.run_id=? AND s.stage='VERIFY_RESULT' AND s.state='VERIFIED' AND x.role='RESULT' AND x.ordinal=0",run));need(rows.size()==1,INPUT_UNAVAILABLE);var row=rows.getFirst();need("SUCCEEDED".equals(row.get("run_state")) && "SUCCEEDED".equals(row.get("attempt_state")) && row.get("artifact_id").equals(row.get("result_artifact_id")),INPUT_CHANGED);
        var files=new PreflightFiles(guard,c.run,c.attempt,(UUID)row.get("checkpoint_id"),"VERIFY_RESULT");RssGoldExecution.verifyStageAnchor(files);var anchor=SourceJson.parse(files.read("verified.json",65536));byte[] evidence=(byte[])row.get("evidence_bytes");need(SourceJson.sha(files.read("verified.json",65536)).equals(row.get("result_sha256")) && SourceJson.sha(evidence).equals(row.get("evidence_sha256")) && SourceJson.sha(evidence).equals(anchor.get("artifactSha256").stringValue()) && c.inputSha.equals(anchor.get("inputSha256").stringValue()) && c.runtime.digest.equals(anchor.get("runtimeSha256").stringValue()) && Arrays.equals(evidence,files.read("selection.json",PreflightFiles.LARGE)),INPUT_CHANGED);
        var e=SourceJson.parse(evidence,PreflightFiles.LARGE);need(e.get("inputs").equals(RssContentInputs.dependencies(c.gold,c.reference)) && e.get("nativeFingerprint").stringValue().equals(row.get("native_identity")) && e.get("storageBindingId").stringValue().equals(row.get("storage_binding_id")) && e.get("relativeAddress").stringValue().equals(row.get("relative_address")) && "CONTENT".equals(row.get("kind")),INPUT_CHANGED);
        var deps=tx.required(()->jdbc.queryForList("SELECT role,ordinal,dependency_artifact_id FROM ddip_management.artifact_dependencies WHERE artifact_id=? ORDER BY role,ordinal",row.get("artifact_id")));need(deps.size()==2,INPUT_CHANGED);for(int i=0;i<2;i++)need(e.get("inputs").get(i).get("role").stringValue().equals(deps.get(i).get("role")) && ((Number)deps.get(i).get("ordinal")).intValue()==0 && e.get("inputs").get(i).get("artifactId").stringValue().equals(deps.get(i).get("dependency_artifact_id").toString()),INPUT_CHANGED);
        var check=new PreflightFiles(guard,c.run,c.attempt,UUID.randomUUID(),"CHECK_INPUTS");byte[] command=command(c,UUID.randomUUID(),SourceJson.parse(files.read("command.json",PreflightFiles.LARGE),PreflightFiles.LARGE).get("ownerEpoch").longValue(),"VERIFY",e.get("verification").get("prepared"),e.get("verification"));check.write("command.json",command,PreflightFiles.LARGE);need(child(guard,c,check,command,null,false).equals(e.get("verification")),INPUT_CHANGED);return (UUID)row.get("artifact_id");
    }
    private JsonNode child(InstallationHostGuard guard,Context c,PreflightFiles files,byte[] command,Current current,boolean stageChild){boolean spark=SourceJson.parse(command,PreflightFiles.LARGE).get("mode").stringValue().equals("PUBLISH");
        var result=new ReadOnlyVerifierProcess(spark).run(c.runtime.command(files.directory.resolve("command.json")),c.runtime.gold.silver.environment(),files.directory,Duration.ofSeconds(c.runtime.config.get("seconds").intValue()),new ReadOnlyVerifierProcess.Observer(){
            public void beforeStart(){if(stageChild)fault.at(current.stage.stage(),Boundary.BEFORE_AUTHORIZATION,current.stage.owner());check(guard,c,current);need(Arrays.equals(command,files.read("command.json",PreflightFiles.LARGE)),INPUT_CHANGED);if(stageChild){current.stage=workers.authorizePublication(guard,current.stage);fault.at(current.stage.stage(),Boundary.AUTHORIZED,current.stage.owner());check(guard,c,current);need(Arrays.equals(command,files.read("command.json",PreflightFiles.LARGE)),INPUT_CHANGED);}}
            public void started(InstallationHostGuard.ProcessIdentity p){RssGoldExecution.recordChild(files,p);if(stageChild){current.stage=workers.recordPublicationChild(guard,current.stage,p);fault.at(current.stage.stage(),Boundary.CHILD_STARTED,current.stage.owner());}}
            public void heartbeat(){if(current!=null && current.stage!=null)fault.at(current.stage.stage(),Boundary.HEARTBEAT,current.stage.owner());check(guard,c,current);if(current!=null){if(current.stage==null)current.owner=workers.heartbeat(guard,current.owner);else current.stage=workers.heartbeatPublication(guard,current.stage);}}
        });if(current!=null && current.stage!=null)fault.at(current.stage.stage(),Boundary.AFTER_CHILD,current.stage.owner());check(guard,c,current);return RssGoldExecution.response(files,command,result);
    }
    private static byte[] boundAnchor(PreflightFiles files,Context c,byte[] evidence){var a=(tools.jackson.databind.node.ObjectNode)SourceJson.parse(RssGoldExecution.anchor(files));a.put("inputSha256",c.inputSha).put("runtimeSha256",c.runtime.digest);if(evidence!=null)a.put("artifactSha256",SourceJson.sha(evidence));return SourceJson.canonical(a);}
    private static byte[] command(Context c,UUID checkpoint,long epoch,String mode,JsonNode prepared,JsonNode verified){var n=SourceJson.object().put("protocolVersion",1).put("mode",mode).put("runId",c.run.toString()).put("attemptId",c.attempt.toString()).put("ownerEpoch",epoch).put("checkpointId",checkpoint.toString()).put("runtimeSha256",c.runtime.digest).put("inputSha256",c.inputSha).put("referenceBindingId",c.runtime.config.get("referenceBindingId").stringValue());n.set("goldProof",c.gold);n.set("reference",c.reference);n.set("referenceBinding",c.runtime.binding(c.runtime.reference));n.set("content",c.runtime.binding(c.runtime.content));n.set("runtime",c.runtime.gold.silver.nativeRuntime());n.set("prepared",prepared);n.set("verified",verified);return SourceJson.canonical(n);}
}
